// ============================================================================
// data_utils.h - File I/O utilities for Ascend C Kernel direct invocation
// ============================================================================

#ifndef DATA_UTILS_H
#define DATA_UTILS_H

#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>
#include <cerrno>
#include <fstream>

inline bool ReadFile(const std::string &filePath, size_t bufferSize, void *buffer, size_t bufferLen)
{
    if (buffer == nullptr) {
        return false;
    }
    if (bufferSize > bufferLen) {
        return false;
    }

    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        return false;
    }

    file.seekg(0, std::ios::end);
    auto pos = file.tellg();
    if (pos < 0) {
        file.close();
        return false;
    }
    size_t fileSize = static_cast<size_t>(pos);
    file.seekg(0, std::ios::beg);

    if (fileSize != bufferSize) {
        file.close();
        return false;
    }

    file.read(static_cast<char *>(buffer), bufferSize);
    if (!file) {
        file.close();
        return false;
    }

    file.close();
    return true;
}

inline bool WriteFile(const std::string &filePath, const void *buffer, size_t size)
{
    if (buffer == nullptr && size > 0) {
        return false;
    }

    int fd = open(filePath.c_str(), O_RDWR | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        return false;
    }

    size_t totalWritten = 0;
    while (totalWritten < size) {
        ssize_t w = write(fd, static_cast<const char *>(buffer) + totalWritten, size - totalWritten);
        if (w < 0) {
            if (errno == EINTR) continue;
            close(fd);
            return false;
        }
        if (w == 0) {
            close(fd);
            return false;
        }
        totalWritten += static_cast<size_t>(w);
    }
    if (close(fd) != 0) {
        return false;
    }

    return true;
}

#endif

// Local test main — runs the first test case
// Usage: ./add_rms_norm_bias_custom

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include "acl/acl.h"

#ifndef TENSOR_GROUP_INFO_DEFINED
#define TENSOR_GROUP_INFO_DEFINED
// Dtype enum for TensorInfo.dtype:
// 0=float32 1=float16 2=bfloat16 3=int8 4=int16 5=int32 6=int64
// 7=uint8 8=uint16 9=uint32 10=uint64 11=bool
struct TensorInfo {
    const int64_t* shape;
    int64_t numDims;
    int32_t dtype;
};
struct TensorGroupInfo {
    const TensorInfo* tensors;
    int64_t numTensors;
};
#endif

#include <vector>
#include "data_utils.h"

#define ACL_CHECK(expr) do { aclError _ret = (expr); if (_ret != 0) { fprintf(stderr, "[ERROR] %s failed at %s:%d, ret=%d\n", #expr, __FILE__, __LINE__, _ret); return 1; } } while(0)
#define FILE_CHECK(expr) do { if (!(expr)) { fprintf(stderr, "[ERROR] File I/O failed at %s:%d\n", __FILE__, __LINE__); return 1; } } while(0)

#include "kernel.asc"

int main()
{
    int32_t deviceId = 0;
    int64_t availableCoreNum = 0;
    aclrtStream stream = nullptr;

    ACL_CHECK(aclInit(nullptr));
    ACL_CHECK(aclrtSetDevice(deviceId));
    ACL_CHECK(aclrtGetDeviceInfo(deviceId, ACL_DEV_ATTR_VECTOR_CORE_NUM, &availableCoreNum));
    if (availableCoreNum <= 0) {
        return 1;
    }
    ACL_CHECK(aclrtCreateStream(&stream));

    int64_t x_0_shape[] = {1, 64};
    TensorInfo x_tensors[] = {{x_0_shape, 2, 1}};
    TensorGroupInfo info_x = {x_tensors, 1};
    int64_t residual_0_shape[] = {1, 64};
    TensorInfo residual_tensors[] = {{residual_0_shape, 2, 1}};
    TensorGroupInfo info_residual = {residual_tensors, 1};
    int64_t gamma_0_shape[] = {64};
    TensorInfo gamma_tensors[] = {{gamma_0_shape, 1, 1}};
    TensorGroupInfo info_gamma = {gamma_tensors, 1};
    int64_t bias_0_shape[] = {64};
    TensorInfo bias_tensors[] = {{bias_0_shape, 1, 1}};
    TensorGroupInfo info_bias = {bias_tensors, 1};
    int64_t output_0_shape[] = {1, 64};
    TensorInfo output_tensors[] = {{output_0_shape, 2, 1}};
    TensorGroupInfo info_output = {output_tensors, 1};

    float epsilon = 1e-05f;

    uint8_t *inputHost_x = nullptr, *inputDevice_x = nullptr;
    uint8_t *inputHost_residual = nullptr, *inputDevice_residual = nullptr;
    uint8_t *inputHost_gamma = nullptr, *inputDevice_gamma = nullptr;
    uint8_t *inputHost_bias = nullptr, *inputDevice_bias = nullptr;

    uint8_t *outputHost_output = nullptr, *outputDevice_output = nullptr;

    ACL_CHECK(aclrtMallocHost((void **)&inputHost_x, 128));
    ACL_CHECK(aclrtMalloc((void **)&inputDevice_x, 128, ACL_MEM_MALLOC_HUGE_FIRST));
    FILE_CHECK(ReadFile("./input/x.bin", 128, inputHost_x, 128));
    ACL_CHECK(aclrtMemcpy(inputDevice_x, 128, inputHost_x, 128, ACL_MEMCPY_HOST_TO_DEVICE));
    ACL_CHECK(aclrtMallocHost((void **)&inputHost_residual, 128));
    ACL_CHECK(aclrtMalloc((void **)&inputDevice_residual, 128, ACL_MEM_MALLOC_HUGE_FIRST));
    FILE_CHECK(ReadFile("./input/residual.bin", 128, inputHost_residual, 128));
    ACL_CHECK(aclrtMemcpy(inputDevice_residual, 128, inputHost_residual, 128, ACL_MEMCPY_HOST_TO_DEVICE));
    ACL_CHECK(aclrtMallocHost((void **)&inputHost_gamma, 128));
    ACL_CHECK(aclrtMalloc((void **)&inputDevice_gamma, 128, ACL_MEM_MALLOC_HUGE_FIRST));
    FILE_CHECK(ReadFile("./input/gamma.bin", 128, inputHost_gamma, 128));
    ACL_CHECK(aclrtMemcpy(inputDevice_gamma, 128, inputHost_gamma, 128, ACL_MEMCPY_HOST_TO_DEVICE));
    ACL_CHECK(aclrtMallocHost((void **)&inputHost_bias, 128));
    ACL_CHECK(aclrtMalloc((void **)&inputDevice_bias, 128, ACL_MEM_MALLOC_HUGE_FIRST));
    FILE_CHECK(ReadFile("./input/bias.bin", 128, inputHost_bias, 128));
    ACL_CHECK(aclrtMemcpy(inputDevice_bias, 128, inputHost_bias, 128, ACL_MEMCPY_HOST_TO_DEVICE));

    ACL_CHECK(aclrtMallocHost((void **)&outputHost_output, 128));
    ACL_CHECK(aclrtMalloc((void **)&outputDevice_output, 128, ACL_MEM_MALLOC_HUGE_FIRST));

    run_kernel((GM_ADDR)inputDevice_x, info_x, (GM_ADDR)inputDevice_residual, info_residual, (GM_ADDR)inputDevice_gamma, info_gamma, (GM_ADDR)inputDevice_bias, info_bias, (GM_ADDR)outputDevice_output, info_output, availableCoreNum, stream, epsilon);
    auto sync_ret_ = aclrtSynchronizeStreamWithTimeout(stream, 3000);
    if (sync_ret_ != 0) { fprintf(stderr, "[ERROR] aclrtSynchronizeStreamWithTimeout failed, ret=%d\n", sync_ret_); return 1; }

    ACL_CHECK(aclrtMemcpy(outputHost_output, 128, outputDevice_output, 128, ACL_MEMCPY_DEVICE_TO_HOST));
    FILE_CHECK(WriteFile("./output/output.bin", outputHost_output, 128));

    if (inputDevice_x) aclrtFree(inputDevice_x);
    if (inputHost_x) aclrtFreeHost(inputHost_x);
    if (inputDevice_residual) aclrtFree(inputDevice_residual);
    if (inputHost_residual) aclrtFreeHost(inputHost_residual);
    if (inputDevice_gamma) aclrtFree(inputDevice_gamma);
    if (inputHost_gamma) aclrtFreeHost(inputHost_gamma);
    if (inputDevice_bias) aclrtFree(inputDevice_bias);
    if (inputHost_bias) aclrtFreeHost(inputHost_bias);
    if (outputDevice_output) aclrtFree(outputDevice_output);
    if (outputHost_output) aclrtFreeHost(outputHost_output);

    aclrtDestroyStream(stream);
    aclrtResetDevice(deviceId);
    aclFinalize();
    return 0;
}

import numpy as np
import sys
import os

try:
    from ml_dtypes import bfloat16
except ImportError:
    bfloat16 = None

# Per-case output specs: 1 cases
# Each spec: (name, dtype, rtol, atol, tol)
# tol = max fraction of elements allowed to mismatch (0.0 = strict)
case_output_specs = {
    0: [
        ("output", np.float16, 0.001, 0.001, 0.001),
    ],
}

if bfloat16 is None:
    for _cid, _specs in case_output_specs.items():
        for _name, _dtype, _rtol, _atol, _tol in _specs:
            if _dtype is None:
                print(f"ERROR: bfloat16 dtype required for case {_cid} output '{_name}' but ml_dtypes is not installed.")
                print("Install with: pip install ml_dtypes")
                sys.exit(1)

def verify_result(output_path, golden_path, dtype, rtol, atol, tol=0.0):
    output = np.fromfile(output_path, dtype=dtype)
    golden = np.fromfile(golden_path, dtype=dtype)
    total_size = golden.size

    if output.size != golden.size:
        if output.size < golden.size:
            golden = golden[:output.size]
            print(f"WARNING: output {output.size} < golden {total_size} elements, truncated golden to match")
        else:
            print(f"FAILED: output has {output.size} elements, golden has {total_size} — size mismatch")
            return False

    missing = total_size - output.size

    if np.issubdtype(dtype, np.integer) or np.issubdtype(dtype, np.bool_):
        if missing == 0 and np.array_equal(output, golden):
            print(f"PASSED: {os.path.basename(output_path)} vs {os.path.basename(golden_path)}")
            return True
        else:
            diff = np.abs(output.astype(np.int64) - golden.astype(np.int64))
            errors = np.sum(output != golden) + missing
            error_rate = errors / total_size if total_size > 0 else 0.0
            if error_rate <= tol:
                print(f"PASSED (tol={tol}): {os.path.basename(output_path)} vs {os.path.basename(golden_path)}")
                print(f"  Mismatched: {errors}/{total_size} ({error_rate*100:.2f}%)")
                return True
            print(f"FAILED: {os.path.basename(output_path)} vs {os.path.basename(golden_path)}")
            print(f"  Mismatched: {errors}/{total_size} ({error_rate*100:.2f}%), tol={tol}")
            print(f"  Max diff: {np.max(diff) if diff.size > 0 else 0.0}")
            return False

    cmp_output = output.astype(np.float32) if dtype == bfloat16 else output
    cmp_golden = golden.astype(np.float32) if dtype == bfloat16 else golden
    isclose = np.isclose(cmp_output, cmp_golden, rtol=rtol, atol=atol, equal_nan=True)
    errors = np.sum(~isclose) + missing
    error_rate = errors / total_size if total_size > 0 else 0.0
    diff = np.abs(cmp_output - cmp_golden)
    if error_rate <= tol:
        print(f"PASSED: {os.path.basename(output_path)} vs {os.path.basename(golden_path)}")
        if errors > 0:
            print(f"  Mismatched: {errors}/{total_size} ({error_rate*100:.2f}%), tol={tol}")
        print(f"  Max diff: {np.max(diff) if diff.size > 0 else 0.0}")
        return True
    else:
        print(f"FAILED: {os.path.basename(output_path)} vs {os.path.basename(golden_path)}")
        print(f"  Mismatched: {errors}/{total_size} ({error_rate*100:.2f}%), tol={tol}")
        print(f"  Max diff: {np.max(diff) if diff.size > 0 else 0.0}")
        return False

if __name__ == "__main__":
    try:
        case_id = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    except ValueError:
        print(f"Invalid case_id: {sys.argv[1] if len(sys.argv) > 1 else '(none)'}")
        sys.exit(1)
    if case_id not in case_output_specs:
        print(f"Unknown case_id {case_id}. Available: {sorted(case_output_specs.keys())}")
        sys.exit(1)

    output_dir = "output"
    all_pass = True
    specs = case_output_specs[case_id]
    if not specs:
        print(f"Case {case_id}: No outputs to verify (all optional) — PASS")
        sys.exit(0)
    for name, dtype, rtol, atol, tol in specs:
        output_path = os.path.join(output_dir, name + ".bin")
        golden_path = os.path.join(output_dir, "golden_" + name + ".bin")
        if not os.path.exists(output_path):
            print(f"FAILED: output {name}.bin not found")
            all_pass = False
            continue
        if not os.path.exists(golden_path):
            print(f"FAILED: golden_{name}.bin not found")
            all_pass = False
            continue
        if not verify_result(output_path, golden_path, dtype, rtol, atol, tol):
            all_pass = False
    sys.exit(0 if all_pass else 1)

